// --- Brick collision: the ball must bounce off bricks, not plow through them.

// Defect 1 (bounce manquant): the brick is destroyed but the ball is never
// deflected, so it passes straight through. A descending ball that reaches the
// top face of a brick must come back up, out of the brick's rectangle.
function topBrick(state, col = 0) {
  return state.bricks.find((b) => b.row === 0 && b.x === 4 + col * (BRICK_W_FIX + BRICK_GAP));
}

// local alias so the helper above stays readable
const BRICK_W_FIX = 72;

test('bricks: descending ball bounces off the top face (no plow-through)', () => {
  const state = createState(1);
  const brick = topBrick(state);
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 2, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(brick.alive, false, 'brick must be destroyed');
  assert.ok(state.ball.vy < 0, 'vy must flip upward');
  assert.ok(
    state.ball.y + state.ball.r <= brick.y,
    'ball must be pushed back above the brick (out of its rectangle)',
  );
});

// Defect 2 (collant): a bounce that only flips the velocity without pushing the
// ball out leaves it overlapping the brick, so the next frame re-inverts and
// the ball sticks (or oscillates). After resolution the ball must be out of the
// rectangle, keep its direction, and the brick must be scored exactly once.
test('bricks: after a bounce the ball stays out and never re-inverts (no sticking)', () => {
  const state = createState(1);
  const brick = topBrick(state);
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 2, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'bounced upward');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'out of the brick after step 1');
  const scoreAfterHit = state.score;
  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1), 'brick scored exactly once');
  step(state, 1 / 60); // second frame: the ball climbs away
  assert.ok(state.ball.vy < 0, 'direction must not be re-inverted');
  assert.ok(state.ball.y + state.ball.r < brick.y, 'ball keeps climbing away');
  assert.equal(state.score, scoreAfterHit, 'a dead brick is never scored twice');
});

// Defect 3 (double inversion / seam): 2*BALL_R (14) > BRICK_GAP (8), so a ball
// descending onto a seam overlaps the two adjacent bricks at once. A naive
// per-brick `vy = -vy` inverts twice and cancels out: the ball goes through.
// Both bricks must die, and the ball must bounce exactly once.
test('bricks: crossing a seam destroys both bricks and bounces exactly once', () => {
  const state = createState(1);
  const row0 = state.bricks
    .filter((b) => b.row === 0)
    .sort((a, b) => a.x - b.x);
  const a = row0[0];
  const c = row0[1];
  const seamX = a.x + a.w + BRICK_GAP / 2; // centered on the gap
  state.ball = { x: seamX, y: a.y - BALL_R - 2, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(a.alive, false, 'left brick destroyed');
  assert.equal(c.alive, false, 'right brick destroyed');
  assert.ok(state.ball.vy < 0, 'vy must flip exactly once (no cancellation)');
  assert.ok(state.ball.y + state.ball.r <= a.y, 'ball out of both rectangles');
});

// Defect 4 (face vs coin): the bounce axis is the least-penetration one. A side
// hit flips vx only; an exact corner hit (equal penetrations) flips both.
test('bricks: side hit flips vx only, ball pushed out sideways', () => {
  const state = createState(1);
  const brick = topBrick(state);
  state.ball = { x: brick.x - BALL_R - 4, y: brick.y + 5, r: BALL_R, vx: 300, vy: 0 };
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx must flip leftwards');
  assert.equal(state.ball.vy, 0, 'vy must be untouched');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball pushed left of the brick');
});

test('bricks: exact corner hit inverts both components', () => {
  const state = createState(1);
  const brick = topBrick(state);
  // The step ends with the ball center exactly on the brick corner (equal
  // penetrations on the top and the left face).
  state.ball = { x: brick.x + 4, y: brick.y - 6, r: BALL_R, vx: -240, vy: 360 };
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx > 0, 'vx must flip (was -240, moving left)');
  assert.ok(state.ball.vy < 0, 'vy must flip (was +360, moving down)');
  assert.ok(
    state.ball.y + state.ball.r <= brick.y || state.ball.x + state.ball.r <= brick.x,
    'ball out of the brick rectangle',
  );
});

// Defect 5 (traversee / tunneling): with dt capped at 50 ms the max step at
// level 6 is ballSpeed(6) * 0.05 = 35.5 px > BRICK_H + 2*BALL_R = 34 px: the
// ball can cross a whole brick in one frame without ever overlapping it. The
// travelled segment must be swept so the brick is still caught and bounced on.
test('bricks: no tunneling at max dt (level 6 speed crosses a brick in one step)', () => {
  const state = createState(6);
  const brick = topBrick(state);
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'brick must be hit even though the step is 35.5 px');
  assert.ok(state.ball.vy < 0, 'ball must bounce, not tunnel through');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'ball pushed back above the brick');
});

// The physics must give the same outcome at 30 fps and at 144 fps: the sweep
// makes the resolution independent of the frame rate.
test('bricks: same bounce outcome at 30 fps and 144 fps', () => {
  const at = (dt) => {
    const s = createState(2);
    const brick = topBrick(s);
    s.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 2, r: BALL_R, vx: 0, vy: ballSpeed(2) };
    step(s, dt);
    return { brick, ball: s.ball };
  };
  const slow = at(1 / 30);
  const fast = at(1 / 144);
  assert.equal(slow.brick.alive, false);
  assert.equal(fast.brick.alive, false);
  assert.ok(slow.ball.vy < 0 && fast.ball.vy < 0, 'both bounce upward');
  assert.ok(slow.ball.y + slow.ball.r <= slow.brick.y, 'slow: out of rectangle');
  assert.ok(fast.ball.y + fast.ball.r <= fast.brick.y, 'fast: out of rectangle');
});

// The brick grid rows are spaced by BRICK_H + BRICK_GAP; makeBricks must use it.
