// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The per-face bounce lives in bounceBricks() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// True if the segment (px,py)->(x,y) swept by a circle of radius r touches the
// brick: the standard segment-vs-AABB test against the brick inflated by r
// (Liang–Barsky slab clipping). This is what makes high-speed steps safe: a
// step longer than the brick (ballSpeed(6) * 0.05 = 35.5 px > BRICK_H +
// 2*BALL_R = 34 px) still registers as a hit instead of tunneling through.
function sweptHit(px, py, x, y, r, brick) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x - px;
  const dy = y - py;
  let t0 = 0;
  let t1 = 1;

  if (dx === 0) {
    if (px < minX || px > maxX) return false;
  } else {
    let a = (minX - px) / dx;
    let b = (maxX - px) / dx;
    if (a > b) [a, b] = [b, a];
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
    if (t0 > t1) return false;
  }
  if (dy === 0) {
    if (py < minY || py > maxY) return false;
  } else {
    let a = (minY - py) / dy;
    let b = (maxY - py) / dy;
    if (a > b) [a, b] = [b, a];
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
    if (t0 > t1) return false;
  }
  return true;
}

// Which face of the brick the ball hit, computed at the ball's current
// position: the axis of the smallest penetration. Equal penetrations (within a
// tiny epsilon) mean a corner hit, where both components must invert. When the
// ball has already crossed the whole brick in one step (no overlap left at the
// current position), the entry face follows the direction of travel.
const CORNER_EPS = 1e-6;

function hitFace(ball, brick) {
  const dxLeft = ball.x + ball.r - brick.x;
  const dxRight = brick.x + brick.w - (ball.x - ball.r);
  const dyTop = ball.y + ball.r - brick.y;
  const dyBottom = brick.y + brick.h - (ball.y - ball.r);
  const mins = [dxLeft, dxRight, dyTop, dyBottom];
  const faces = ['left', 'right', 'top', 'bottom'];

  if (mins.every((m) => m > 0)) {
    const min = Math.min(...mins);
    const ties = mins.filter((m) => Math.abs(m - min) < CORNER_EPS).length;
    if (ties >= 2) return 'corner';
    return faces[mins.indexOf(min)];
  }

  // Tunneled through: no overlap remains, the entry face follows the velocity.
  if (Math.abs(ball.vx) > Math.abs(ball.vy)) return ball.vx > 0 ? 'left' : 'right';
  if (Math.abs(ball.vy) > Math.abs(ball.vx)) return ball.vy > 0 ? 'top' : 'bottom';
  return 'corner';
}

// Resolves the ball-vs-bricks collisions of one pass. The ball travelled from
// (prevX, prevY) to its current position this step; the segment is swept
// against every live brick, so no brick is crossed unseen (no tunneling).
//
// Each touched brick is destroyed and scored exactly once (dead bricks are
// skipped). The ball bounces at most once per axis per pass (bouncedX/Y): a
// seam between two adjacent bricks must not invert the same component twice
// and cancel out. After a bounce the ball is pushed back out of the brick so
// it never re-inverts on the next frame (no sticking).
export function bounceBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const cx = ball.x; // trajectory endpoint, before any push-out
  const cy = ball.y;
  let bouncedX = false;
  let bouncedY = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!sweptHit(prevX, prevY, cx, cy, ball.r, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const face = hitFace(ball, brick);
    if (face === 'left' || face === 'right') {
      if (!bouncedX) {
        ball.vx = -ball.vx;
        ball.x = face === 'left' ? brick.x - ball.r : brick.x + brick.w + ball.r;
        bouncedX = true;
      }
    } else if (face === 'top' || face === 'bottom') {
      if (!bouncedY) {
        ball.vy = -ball.vy;
        ball.y = face === 'top' ? brick.y - ball.r : brick.y + brick.h + ball.r;
        bouncedY = true;
      }
    } else if (!bouncedX || !bouncedY) {
      // Corner: both components invert (once per axis), then push the ball out
      // along the axis it was crossing.
      const dirX = Math.sign(ball.vx);
      const dirY = Math.sign(ball.vy);
      if (!bouncedX) {
        ball.vx = -ball.vx;
        bouncedX = true;
      }
      if (!bouncedY) {
        ball.vy = -ball.vy;
        bouncedY = true;
      }
      if (Math.abs(dirY) >= Math.abs(dirX)) {
        ball.y = dirY > 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      } else {
        ball.x = dirX > 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      }
    }
  }
}

